"use client";

import { useRef } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";

/**
 * "Golden Vortex" — a raymarched SDF scene, ported from the standalone
 * index.html shader built for this hero. 5 long, rounded, bent slabs
 * ("ribbons") are blended together with a smooth-min, then warped through
 * a swirl domain function anchored toward the upper-left of frame. Near
 * that anchor the swirl strength is huge (k / r^2), so the ribbons curl
 * into a tight concentric spiral there; far from it the warp fades out
 * and the same ribbons read as broad sweeping sheets extending right —
 * one continuous surface, not two separate effects.
 *
 * Lit with a Blinn-Phong-style key light (tight + soft specular lobes,
 * Fresnel, soft shadows, a cheap SDF ambient-occlusion trick) and shaded
 * through an 8-stop gold ramp (deep near-black bronze -> champagne ->
 * near-white hot highlight) instead of a flat hue, so the material reads
 * as polished metal rather than painted color.
 *
 * Unlike LiquidCarbonCanvas.tsx (two-pass: offscreen raymarch buffer +
 * a separate depth-of-field blur pass), this is single-pass — one
 * fullscreen shader, no render target/portal-scene needed — but it's
 * still a per-pixel raymarch (~100 distance-field evaluations per pixel
 * between the main march, normals, shadow and AO), so it keeps the same
 * ~30fps frame cap and dpr=1 pinning LiquidCarbonCanvas uses, rather
 * than CreamGradientCanvas's cheaper "render at full rate" approach.
 */

const vertexShader = /* glsl */ `
  void main() {
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

const fragmentShader = /* glsl */ `
  precision highp float;
  uniform float iTime;
  uniform vec2 iResolution;
  #define time iTime
  #define res iResolution

  // Luxury gold/champagne ramp (deep bronze-black -> hot near-white).
  const vec3 c0 = vec3(0.0863, 0.0471, 0.0078); // #160C02
  const vec3 c1 = vec3(0.2275, 0.1294, 0.0196); // #3A2105
  const vec3 c2 = vec3(0.3765, 0.2510, 0.0392); // #60400A
  const vec3 c3 = vec3(0.6039, 0.4118, 0.0588); // #9A690F
  const vec3 c4 = vec3(0.7882, 0.6039, 0.1961); // #C99A32
  const vec3 c5 = vec3(0.9098, 0.7765, 0.3529); // #E8C65A
  const vec3 c6 = vec3(1.0, 0.9412, 0.6392);    // #FFF0A3
  const vec3 c7 = vec3(1.0, 0.9725, 0.8157);    // #FFF8D0

  vec3 goldRamp(float x) {
    x = clamp(x, 0.0, 1.0);
    float seg = x * 7.0;
    float i = floor(seg);
    float f = fract(seg);
    if (i < 0.5) return mix(c0, c1, f);
    if (i < 1.5) return mix(c1, c2, f);
    if (i < 2.5) return mix(c2, c3, f);
    if (i < 3.5) return mix(c3, c4, f);
    if (i < 4.5) return mix(c4, c5, f);
    if (i < 5.5) return mix(c5, c6, f);
    return mix(c6, c7, f);
  }

  void pR(inout vec2 p, float a) {
    p = cos(a) * p + sin(a) * vec2(p.y, -p.x);
  }

  // polynomial smooth-min (IQ) — organic blending between ribbons
  float smin(float a, float b, float k) {
    float hh = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, hh) - k * hh * (1.0 - hh);
  }

  // swirl domain warp: rotates points around c by an angle that grows
  // sharply as r -> 0, so shapes near c curl into a spiral while shapes
  // far from c are left almost unrotated.
  vec2 swirl(vec2 p, vec2 c, float k) {
    vec2 d = p - c;
    float r = length(d);
    float a = atan(d.y, d.x);
    a += k / (0.55 + r * r);
    return c + r * vec2(cos(a), sin(a));
  }

  float sdBox(vec3 p, vec3 b) {
    vec3 d = abs(p) - b;
    return min(max(d.x, max(d.y, d.z)), 0.0) + length(max(d, 0.0));
  }

  // 3D value noise (IQ) — only used as a small surface-grain offset,
  // never as the shape itself.
  float noise(vec3 p) {
    vec3 ip = floor(p);
    p -= ip;
    vec3 s = vec3(7.0, 157.0, 113.0);
    vec4 hn = vec4(0.0, s.yz, s.y + s.z) + dot(ip, s);
    p = p * p * (3.0 - 2.0 * p);
    hn = mix(fract(sin(hn) * 43758.5), fract(sin(hn + s.x) * 43758.5), p.x);
    hn.xy = mix(hn.xz, hn.yw, p.y);
    return mix(hn.x, hn.y, p.z);
  }

  const int RIBBONS = 5;

  float map(vec3 p) {
    vec2 warped = swirl(p.xy, vec2(-0.95, 0.32), 2.5 + 0.15 * sin(time * 0.04));
    vec3 q = vec3(warped, p.z);
    // Gentle bounded sway rather than unbounded spin, so the asymmetric
    // left-spiral / right-sweep composition never drifts away over a
    // long-running hero background (luxurious, not fast).
    pR(q.xy, sin(time * 0.018) * 0.14);

    float d = 1e5;
    for (int i = 0; i < RIBBONS; i++) {
      float fi = float(i);
      vec3 r = q;
      // layer-by-layer twist + spread -> the "multiple concentric
      // flowing folds" / "smaller curved ribbons layered on top"
      pR(r.yz, 0.5 + fi * 0.55 + 0.06 * sin(time * 0.025 + fi * 1.7));
      r.y -= fi * 0.62 - 1.25;
      // slow sweeping bend along the ribbon's length
      r.y -= 0.55 * sin(0.55 * r.x - fi * 0.6 + time * 0.015);
      float halfThk = 0.15 + 0.025 * fi;
      float slab = sdBox(r, vec3(4.6, halfThk, 0.9)) - 0.05; // rounded edges
      slab -= 0.045 * noise(r * 2.2 + fi * 11.3 + time * 0.008); // subtle grain
      d = smin(d, slab, 0.5);
    }
    return d;
  }

  vec3 calcNormal(vec3 pos) {
    float eps = 0.0008;
    float d = map(pos);
    return normalize(vec3(
      map(pos + vec3(eps, 0.0, 0.0)) - d,
      map(pos + vec3(0.0, eps, 0.0)) - d,
      map(pos + vec3(0.0, 0.0, eps)) - d
    ));
  }

  // sphere tracing, early-exits on convergence or max distance
  float castRayx(vec3 ro, vec3 rd) {
    float sgn = (map(ro) < 0.0) ? -1.0 : 1.0;
    float precis = 0.0006;
    float h = precis * 2.0;
    float t = 0.0;
    for (int i = 0; i < 80; i++) {
      if (abs(h) < precis || t > 12.0) break;
      h = sgn * map(ro + rd * t);
      t += h * 0.9;
    }
    return t;
  }

  float softshadow(vec3 ro, vec3 rd) {
    float sh = 1.0;
    float t = 0.03;
    for (int i = 0; i < 12; i++) {
      if (t > 6.0) continue;
      float h = map(ro + rd * t);
      sh = min(sh, 6.0 * h / t);
      t += clamp(h, 0.02, 0.4);
    }
    return clamp(sh, 0.0, 1.0);
  }

  // cheap SDF ambient occlusion (IQ) — darkens deep grooves between folds
  float calcAO(vec3 pos, vec3 nor) {
    float occ = 0.0;
    float weight = 1.0;
    for (int i = 1; i <= 4; i++) {
      float hr = 0.05 * float(i);
      float dd = map(pos + nor * hr);
      occ += (hr - dd) * weight;
      weight *= 0.6;
    }
    return clamp(1.0 - 1.6 * occ, 0.0, 1.0);
  }

  void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / res.xy;
    vec2 p = uv * 2.0 - 1.0;

    vec3 dir = normalize(vec3(2.0 * fragCoord - res.xy, res.y));
    vec3 org = vec3(0.0, 0.0, -3.3);

    vec3 lig = normalize(vec3(0.4, 0.75, -0.5));

    float t = castRayx(org, dir);
    vec3 rgb = c0; // deep bronze-black void where nothing is hit

    if (t < 12.0) {
      vec3 pos = org + dir * t;
      vec3 nor = calcNormal(pos);

      float diff = max(dot(nor, lig), 0.0);
      vec3 refl = reflect(dir, nor);
      float specTight = pow(max(dot(refl, lig), 0.0), 42.0); // thin bright edge highlight
      float specSoft = pow(max(dot(refl, lig), 0.0), 8.0) * 0.35; // broader glossy sheen
      float fres = pow(1.0 - clamp(dot(nor, -dir), 0.0, 1.0), 3.0); // Fresnel rim

      float shadow = softshadow(pos + nor * 0.02, lig);
      float ao = calcAO(pos, nor);

      float tone = diff * 0.5 + specTight * 0.85 + specSoft + fres * 0.3;
      tone *= mix(0.35, 1.0, shadow);
      tone *= ao;

      float depth = clamp(1.0 - 0.1 * t, 0.0, 1.0);

      rgb = goldRamp(tone);
      rgb += c7 * pow(specTight, 3.0) * 0.7; // hot pinpoint specular
      rgb = mix(c0, rgb, depth); // fade to the void with distance
    }

    // soft corner vignette
    float edge = smoothstep(0.35, 1.55, length(p));
    rgb = mix(rgb, c0 * 0.6, edge * 0.35);

    fragColor = vec4(rgb, 1.0);
  }

  void main() {
    mainImage(gl_FragColor, gl_FragCoord.xy);
  }
`;

// Same reasoning as LiquidCarbonCanvas.tsx: this is a slow, ambient,
// per-pixel raymarch — capping to ~30fps roughly halves sustained GPU
// cost with no visible difference for motion this gentle.
const TARGET_FRAME_INTERVAL = 1 / 30;

function GoldenVortexPlane() {
  const { gl, size } = useThree();
  const materialRef = useRef<THREE.ShaderMaterial>(null);
  const lastRenderTimeRef = useRef(0);
  const hasRenderedRef = useRef(false);

  useFrame((state) => {
    const t = state.clock.elapsedTime;
    if (hasRenderedRef.current && t - lastRenderTimeRef.current < TARGET_FRAME_INTERVAL) {
      return;
    }
    hasRenderedRef.current = true;
    lastRenderTimeRef.current = t;

    if (materialRef.current) {
      const dpr = gl.getPixelRatio();
      const w = Math.max(1, Math.floor(size.width * dpr));
      const h = Math.max(1, Math.floor(size.height * dpr));
      materialRef.current.uniforms.iTime.value = t;
      materialRef.current.uniforms.iResolution.value.set(w, h);
    }
  });

  return (
    <mesh frustumCulled={false}>
      <planeGeometry args={[2, 2]} />
      <shaderMaterial
        ref={materialRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={{
          iTime: { value: 0 },
          iResolution: { value: new THREE.Vector2(1, 1) },
        }}
      />
    </mesh>
  );
}

export default function GoldenVortexCanvas({ inView }: { inView: boolean }) {
  return (
    <Canvas
      gl={{
        antialias: false,
        powerPreference: "high-performance",
        alpha: false,
        preserveDrawingBuffer: true,
      }}
      dpr={1}
      frameloop={inView ? "always" : "never"}
      camera={{ position: [0, 0, 1] }}
      // Safety net: paint the deep bronze-black void the instant the
      // context exists, before the first real shader frame runs, so a
      // slow first draw never flashes opaque black (alpha is false above).
      onCreated={({ gl }) => {
        gl.setClearColor(0x120a02, 1);
        gl.clear();
      }}
    >
      <GoldenVortexPlane />
    </Canvas>
  );
}
